import cv2,numpy as np
ref=cv2.imread('output/qa/sync_reference_10s.jpg');sift=cv2.SIFT_create(nfeatures=5000,contrastThreshold=0.015)
panels={'sd_tl':(0,0,262,196),'sd_tr':(262,0,524,196),'sd_bl':(0,196,262,392),'sd_br':(262,196,524,392),'hd_mid':(524,0,1222,392),'hd_right':(1222,0,1920,392)}
for c in 'ABCD':
 im=cv2.imread('output/qa/CAM_'+c+'_10s.jpg'); k1,d1=sift.detectAndCompute(im,None)
 for n,(x1,y1,x2,y2) in panels.items():
  p=cv2.resize(ref[y1:y2,x1:x2],None,fx=2,fy=2);k2,d2=sift.detectAndCompute(p,None)
  pairs=cv2.BFMatcher().knnMatch(d1,d2,k=2);good=[m for m,n2 in pairs if m.distance<.72*n2.distance]
  if len(good)>=8:
   src=np.float32([k1[m.queryIdx].pt for m in good]);dst=np.float32([k2[m.trainIdx].pt for m in good]);h,mask=cv2.findHomography(src,dst,cv2.RANSAC,3)
   print(c,n,'matches',len(good),'inliers',int(mask.sum()))
   if mask.sum()>25:
    np.save('output/qa/H_'+c+'_'+n+'.npy',h)
